using System.Buffers.Binary;
using System.Numerics;
using ClothingSkeleton.Core;

var passed = 0;
void Check(bool condition, string name) { if (!condition) throw new Exception("FAIL: " + name); Console.WriteLine("PASS: " + name); passed++; }
void Reject(Action action, string name) { try { action(); } catch (Exception e) when (e is InvalidDataException or System.Xml.XmlException) { Check(true, name); return; } throw new Exception("FAIL: " + name); }
byte[] Sklb()
{
    var data = new byte[96];
    BinaryPrimitives.WriteUInt32LittleEndian(data, 0x736B6C62);
    BinaryPrimitives.WriteUInt16LittleEndian(data.AsSpan(4), 0x3030);
    BinaryPrimitives.WriteUInt16LittleEndian(data.AsSpan(6), 0x3133);
    BinaryPrimitives.WriteInt32LittleEndian(data.AsSpan(8), 24);
    BinaryPrimitives.WriteInt32LittleEndian(data.AsSpan(12), 48);
    for (var i = 16; i < data.Length; i++) data[i] = (byte)(i * 7);
    return data;
}
var source = Sklb();
var sklb = SklbContainer.Parse(source);
Check(sklb.OriginalBytes().SequenceEqual(source), "untouched wrapper round trip is byte exact");
var payload = Enumerable.Repeat((byte)0x55, 72).ToArray();
var changed = sklb.WithPayload(payload);
Check(changed.AsSpan(0, 48).SequenceEqual(source.AsSpan(0, 48)), "opaque wrapper bytes survive payload replacement");
Check(changed.AsSpan(48).SequenceEqual(payload), "replacement payload has correct boundary");
var broken = Sklb(); broken[0] = 0; Reject(() => SklbContainer.Parse(broken), "invalid magic rejected");
broken = Sklb(); BinaryPrimitives.WriteInt32LittleEndian(broken.AsSpan(12), int.MaxValue); Reject(() => SklbContainer.Parse(broken), "oversized offset rejected");
broken = Sklb(); BinaryPrimitives.WriteInt32LittleEndian(broken.AsSpan(12), -1); Reject(() => SklbContainer.Parse(broken), "negative offset rejected");
broken = Sklb(); broken[4] = 0x31; Reject(() => SklbContainer.Parse(broken), "unknown complete version rejected");
broken = Sklb(); BinaryPrimitives.WriteInt32LittleEndian(broken.AsSpan(8), 25); Reject(() => SklbContainer.Parse(broken), "misaligned wrapper descriptor rejected");
Reject(() => SklbContainer.Parse(new byte[8]), "truncated file rejected");
Reject(() => sklb.WithPayload(new byte[1]), "empty replacement rejected");
source[20] ^= 1; Check(sklb.OriginalBytes()[20] != source[20], "caller buffer cannot mutate container");
