Check(Has(baseline with { Bones = [root, child with { Name = "renamed" }] }, "B003"), "renamed original rejected");
Check(Has(baseline with { Bones = [root, child with { ParentId = null }] }, "B003"), "reparented original rejected");
Check(Has(baseline with { Bones = [root, child with { Translation = Vector3.One }] }, "B003"), "changed original rest pose rejected");
