Check(Has(candidate with { Bones = [root, child, leaf with { Name = child.Name }] }, "B005"), "duplicate game bone name rejected");
Check(Has(candidate with { Bones = [root, child, leaf with { ParentId = leaf.Id }] }, "B002"), "self cycle rejected");
Check(Has(candidate with { Bones = [root, child, leaf with { ParentId = leaf2.Id }, leaf2] }, "B002"), "two bone cycle rejected");
Check(Has(candidate with { Bones = [root, child, leaf with { ParentId = Guid.NewGuid() }] }, "B001"), "missing parent rejected");
Check(Has(candidate with { Bones = [root, child, leaf with { Translation = new(float.NaN, 0, 0) }] }, "T001"), "NaN rejected");
Check(Has(candidate with { Bones = [root, child, leaf with { Rotation = new(0, 0, 0, 0) }] }, "T002"), "zero quaternion rejected");
Check(Has(candidate with { Bones = [root, child, leaf with { Scale = new(-1, 1, 1) }] }, "T003"), "negative scale rejected");
Check(Has(candidate with { Bones = [root, child, leaf with { Scale = new(2, 1, 1) }] }, "T003"), "new nonuniform scale rejected");
