var template = "<hktagfile version='2' sdkversion='hk_2014.2.5-r1'><class name='unchanged'/><object id='#1' type='hkaSkeleton'><array name='bones' size='2'><struct><string name='name'>n_root</string></struct><struct><string name='name'>j_cloth</string></struct></array><array name='parentIndices' size='2'>-1 0</array><array name='referencePose' size='2'><vec12>original-exact-pose-0</vec12><vec12>original-exact-pose-1</vec12></array></object></hktagfile>";
