byte[] Layered()
{
    var bytes=new byte[96];
    BinaryPrimitives.WriteUInt32LittleEndian(bytes,0x736b6c62);
    BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(4),0x3030);
    BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(6),0x3133);
    BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(8),24);
    BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(12),64);
    BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(32),0x616c7068);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(36),1);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(38),8);
    BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(40),25);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(44),2);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(46),0);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(48),1);
    return bytes;
}
var layered=SklbContainer.Parse(Layered());
Check(SklbLayerTable.Read(layered,2).Single().Id==25,"original SKLB layer ID is read without inventing a new layer");
var layerAppend=SklbContainer.Parse(SklbLayerTable.Append(layered,layered.Payload.Span,baseline,candidate));
Check(SklbLayerTable.Read(layerAppend,4).Single().BoneIndices.SequenceEqual(new[]{0,1,2,3}),"new bone chain inherits the parent's layer and retains original membership");
var many=baseline.Bones.ToList();
for(var i=0;i<20;i++)many.Add(new BoneRecord{Name="chain_"+i,ParentId=many[^1].Id});
var expanded=SklbContainer.Parse(SklbLayerTable.Append(layered,layered.Payload.Span,baseline,baseline with{Bones=many}));
Check(expanded.HavokOffset>layered.HavokOffset && expanded.HavokOffset%16==0 && expanded.Payload.Span.SequenceEqual(layered.Payload.Span),"layer growth relocates aligned HKX without changing its bytes");
Check(expanded.Header.Span[..12].SequenceEqual(layered.Header.Span[..12]) && expanded.Header.Span[16..32].SequenceEqual(layered.Header.Span[16..32]),"layer growth retains unrelated descriptor bytes");
var malformed=Layered();BinaryPrimitives.WriteInt16LittleEndian(malformed.AsSpan(38),32767);
Reject(()=>SklbLayerTable.Read(SklbContainer.Parse(malformed),2),"corrupt layer offset rejected");
malformed=Layered();BinaryPrimitives.WriteInt16LittleEndian(malformed.AsSpan(48),2);
Reject(()=>SklbLayerTable.Read(SklbContainer.Parse(malformed),2),"out-of-range layer bone index rejected");
Reject(()=>SklbLayerTable.Append(layered,layered.Payload.Span,baseline,candidate with{Bones=[root,child,leaf with{ParentId=null},leaf2]}),"unparented new bone cannot silently omit its layer");
malformed=Layered();malformed[63]=1;
Reject(()=>SklbLayerTable.Append(SklbContainer.Parse(malformed),layered.Payload.Span,baseline,candidate),"opaque nonzero padding blocks unsupported layer resizing");
