byte[] AttachmentSklb()
{
    var bytes=new byte[112];
    BinaryPrimitives.WriteUInt32LittleEndian(bytes,0x736b6c62);
    BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(4),0x3030);
    BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(6),0x3133);
    BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(8),48);
    BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(12),80);
    BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(20),201);
    for(var i=0;i<4;i++)BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(24+4*i),-1);
    BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(48),0x616c7068);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(52),1);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(54),8);
    BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(56),25);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(60),2);
    BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(64),1);
    return bytes;
}
var attachmentOriginal=SklbContainer.Parse(AttachmentSklb());
const string attachmentPath="chara/human/c0201/skeleton/top/t0100/skl_c0201t0100.sklb";
var attachmentBaseline=baseline with{SourceSha256=attachmentOriginal.Sha256,SourceGamePath=attachmentPath};
var referenceRoot=new BoneRecord{Name="n_hara",OriginalIndex=0};
var referenceHand=new BoneRecord{Name="j_te_l",OriginalIndex=1,ParentId=referenceRoot.Id,Translation=new(.4f,1.2f,.1f),Rotation=Quaternion.CreateFromAxisAngle(Vector3.UnitZ,.6f)};
var attachmentReference=new SkeletonDocument{Name="reference",SourceSha256=new string('b',64),SourceGamePath="chara/human/c0201/skeleton/base/b0001/skl_c0201b0001.sklb",Bones=[referenceRoot,referenceHand]};
var mount=EquipmentAttachment.Create(attachmentOriginal,attachmentBaseline,attachmentReference,"j_te_l");
Check(mount.Changed && mount.Info.OriginalParentBone=="n_hara" && mount.Target.BoneIndex==1,"equipment attachment resolves the hand by the original reference's actual index");
var logical=candidate with{SourceSha256=attachmentBaseline.SourceSha256,SourceGamePath=attachmentPath,AttachmentTargetBone="j_te_l"};
var native=mount.Materialize(SkeletonValidator.OrderedForAppend(logical,attachmentBaseline));
Check(native[0].Translation==referenceHand.Translation && MathF.Abs(Quaternion.Dot(native[0].Rotation,referenceHand.Rotation))>.99999f,"equipment root adopts the target hand's model-space rest pose");
Check(native.Skip(1).SequenceEqual(ordered.Skip(1)),"controlled root attachment retains every original and added child transform and parent");
var mountedBytes=mount.ApplyWrapper(attachmentOriginal.OriginalBytes());
Check(BinaryPrimitives.ReadInt16LittleEndian(mountedBytes.AsSpan(16))==1 && mountedBytes.Where((v,i)=>i is not (16 or 17)).SequenceEqual(attachmentOriginal.OriginalBytes().Where((v,i)=>i is not (16 or 17))),"mount changes only the native connection field in the SKLB wrapper");
var unchangedMount=EquipmentAttachment.Create(attachmentOriginal,attachmentBaseline,attachmentReference,"n_hara");
Check(!unchangedMount.Changed && unchangedMount.Materialize(ordered).SequenceEqual(ordered) && unchangedMount.ApplyWrapper(attachmentOriginal.OriginalBytes()).SequenceEqual(attachmentOriginal.OriginalBytes()),"selecting the original attachment preserves exact source root and wrapper bytes");
GltfExchange.Export(logical,gltfPath);
var mountedExchange=GltfExchange.Import(gltfPath,attachmentBaseline);
Check(mountedExchange.AttachmentTargetBone=="j_te_l" && mountedExchange.Bones.Single(b=>b.Id==root.Id)==root,"hashed glTF carries the attachment choice without altering protected source bones");
Reject(()=>HavokXmlAppend.Apply(template,attachmentBaseline,logical),"native conversion cannot silently ignore an unvalidated attachment selection");
Reject(()=>HavokXmlAppend.Apply(template,attachmentBaseline,logical with{AttachmentTargetBone=null},mount),"attachment plan cannot change the root without an explicit exchange selection");
Reject(()=>HavokXmlAppend.Apply(template,attachmentBaseline with{SourceSha256=new string('c',64)},logical with{SourceSha256=new string('c',64)},mount),"attachment plan is bound to the original source hash");
var mountedXml=System.Xml.Linq.XDocument.Parse(HavokXmlAppend.Apply(template,attachmentBaseline,logical,mount));
Check(mountedXml.Descendants("vec12").First().Value!="original-exact-pose-0" && mountedXml.Descendants("vec12").Skip(1).First().Value=="original-exact-pose-1","native attachment rewrites only the controlled root and preserves exact original child pose text");
Reject(()=>EquipmentAttachment.Create(attachmentOriginal,attachmentBaseline,attachmentReference,"missing_hand"),"missing body attachment target rejected");
Reject(()=>EquipmentAttachment.Create(attachmentOriginal,attachmentBaseline,attachmentReference with{SourceGamePath="chara/human/c0101/skeleton/base/b0001/skl_c0101b0001.sklb"},"j_te_l"),"attachment cannot reference another race or gender skeleton");
Reject(()=>EquipmentAttachment.Create(attachmentOriginal,attachmentBaseline with{Bones=[root with{Translation=Vector3.One},child]},attachmentReference,"j_te_l"),"unrecognized source root and connection alignment rejected");
Reject(()=>EquipmentAttachment.Create(attachmentOriginal,attachmentBaseline,attachmentReference with{Bones=[referenceRoot,referenceHand with{Scale=new(2,1,1)}]},"j_te_l"),"scaled attachment references cannot silently shear the equipment skeleton");
Reject(()=>EquipmentAttachment.Create(attachmentOriginal,attachmentBaseline with{MapperCount=1},attachmentReference,"j_te_l"),"existing skeleton mappers remain protected when choosing a body attachment");
var wrongDescriptor=AttachmentSklb();BinaryPrimitives.WriteInt32LittleEndian(wrongDescriptor.AsSpan(24),201);
var wrongContainer=SklbContainer.Parse(wrongDescriptor);
Reject(()=>EquipmentAttachment.Create(wrongContainer,attachmentBaseline with{SourceSha256=wrongContainer.Sha256},attachmentReference,"j_te_l"),"wrapper mapper references block unsupported direct attachment changes");
Reject(()=>EquipmentAttachment.Create(attachmentOriginal,attachmentBaseline with{Bones=[root,child with{ParentId=null}]},attachmentReference,"j_te_l"),"multiple equipment roots cannot be attached by guessing a connection");
var mountedLayer=SklbContainer.Parse(mount.ApplyWrapper(SklbLayerTable.Append(attachmentOriginal,attachmentOriginal.Payload.Span,attachmentBaseline,logical)));
Check(SklbLayerTable.Read(mountedLayer,4).Single().BoneIndices.SequenceEqual(new[]{0,1,2,3}) && mountedLayer.Payload.Span.SequenceEqual(attachmentOriginal.Payload.Span),"attachment and added layer membership compose without changing the Havok payload boundary");
